export class BVec2 {
	// Fields are `declare`d instead of parameter properties so no class fields
	// are emitted (see the note in `Vec2`).
	/** The `x` element. */
	declare x: boolean;
	/** The `y` element. */
	declare y: boolean;

	constructor(x: boolean, y: boolean) {
		this.x = x;
		this.y = y;
	}

	/** All false. (false, false..) */
	static get FALSE() {
		return new BVec2(false, false);
	}

	/** All true. (true, true..) */
	static get TRUE() {
		return new BVec2(true, true);
	}

	/** Creates a vector with all elements set to v. */
	static splat(v: boolean): BVec2 {
		return new BVec2(v, v);
	}

	/**
	 * Returns a bitmask with the lowest 2 bits set from the elements of BVec2.
	 * A true element results in a 1 bit and a false element in a 0 bit. Element x goes into the first lowest bit, element y into the second, etc.
	 */
	bitmask(): number {
		return (this.x ? 1 : 0) | (this.y ? 2 : 0);
	}

	/** Returns true if any of the elements are true, false otherwise. */
	any(): boolean {
		return this.x || this.y;
	}

	/** Returns true if all the elements are true, false otherwise. */
	all(): boolean {
		return this.x && this.y;
	}

	/** Tests the value at index. */
	test(index: 0 | 1): boolean | undefined {
		switch (index) {
			case 0:
				return this.x;
			case 1:
				return this.y;
			default:
				return undefined;
		}
	}

	/** Sets the element at index. */
	set(index: 0 | 1, value: boolean): void {
		switch (index) {
			case 0: {
				this.x = value;
				break;
			}
			case 1: {
				this.y = value;
				break;
			}
			default:
				break;
		}
	}

	/** Performs the & operation. */
	bitand(rhs: BVec2): BVec2 {
		return new BVec2(this.x && rhs.x, this.y && rhs.y);
	}

	/** Performs the | operation. */
	bitor(rhs: BVec2): BVec2 {
		return new BVec2(this.x || rhs.x, this.y || rhs.y);
	}

	/** Performs the ^ operation. */
	bitxor(rhs: BVec2): BVec2 {
		return new BVec2(this.x !== rhs.x, this.y !== rhs.y);
	}

	/** Returns the negation. */
	not(): BVec2 {
		return new BVec2(!this.x, !this.y);
	}

	/** This method tests for self and other values to be equal, and is used by ==. */
	eq(rhs: BVec2 | boolean): boolean {
		if (typeof rhs === "boolean") {
			return this.x === rhs && this.y === rhs;
		}

		return this.x === rhs.x && this.y === rhs.y;
	}

	/** This method tests for !=. */
	ne(rhs: BVec2 | boolean): boolean {
		if (typeof rhs === "boolean") {
			return this.x !== rhs || this.y !== rhs;
		}

		return this.x !== rhs.x || this.y !== rhs.y;
	}

	/** Prints out a formatted output of the instance. */
	toString() {
		return `BVec2(${this.x}, ${this.y})`;
	}
}
